ssize_t handle_macvtap_queue(struct macvtap_queue *q, struct msghdr *m,
                             const struct iovec *iv, unsigned long total_len,
                             size_t count, int noblock) {
    struct sk_buff *skb = NULL;
    size_t len = 0;
    ssize_t ret = 0;
    int zero_copy = 0;

    if (!q || !m || !iv || total_len == 0 || count == 0) {
        return -EINVAL;
    }

    if (total_len > USHRT_MAX) {
        return -EMSGSIZE;
    }

    if (noblock && !(m->msg_flags & MSG_DONTWAIT)) {
        return -EAGAIN;
    }

    skb = alloc_skb(128, GFP_KERNEL);
    if (!skb) {
        return -ENOMEM;
    }

    if (zero_copy) {
        if (skb_zerocopy_sg(skb, iv, count, total_len)) {
            kfree_skb(skb);
            return -EFAULT;
        }
    } else {
        if (skb_copy_datagram_from_iter(skb, 0, &m->msg_iter, total_len)) {
            kfree_skb(skb);
            return -EFAULT;
        }
    }

    skb_reset_network_header(skb);
    skb_set_transport_header(skb, sizeof(struct ethhdr));

    if (q->vlan_dev) {
        skb = __vlan_put_tag(skb, q->vlan_dev, q->vlan_id);
        if (!skb) {
            return -ENOMEM;
        }
    }

    ret = dev_queue_xmit(skb);
    if (ret < 0) {
        kfree_skb(skb);
    }

    return (ret < 0) ? ret : total_len;
}

ssize_t handle_macvtap_queue(struct macvtap_queue *q, struct msghdr *m,
                             const struct iovec *iv, unsigned long total_len,
                             size_t count, int noblock) {
    struct sk_buff *skb;
    ssize_t copied = 0;
    int err = 0;
    size_t i;

    if (!q || !m || !iv || total_len == 0)
        return -EINVAL;

    if (count == 0)
        return 0;

    /* Check for virtual network header requirements */
    if (m->msg_flags & MSG_OOB) {
        return -EOPNOTSUPP;
    }

    skb = alloc_skb(1500, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    for (i = 0; i < count && copied < total_len; i++) {
        size_t len = min(iv[i].iov_len, total_len - copied);
        char *buf;

        buf = kmalloc(len, GFP_KERNEL);
        if (!buf) {
            err = -ENOMEM;
            break;
        }

        if (copy_from_user(buf, iv[i].iov_base, len)) {
            kfree(buf);
            err = -EFAULT;
            break;
        }

        skb_put_data(skb, buf, len);
        copied += len;
        kfree(buf);
    }

    if (err) {
        kfree_skb(skb);
        return err;
    }

    skb->protocol = htons(ETH_P_IP);
    skb->dev = q->vdev;

    if (q->vlan_dev) {
        skb->dev = q->vlan_dev;
    }

    err = dev_queue_xmit(skb);
    if (err < 0) {
        return err;
    }

    return copied;
}

ssize_t handle_macvtap_queue_data(struct macvtap_queue *q, struct msghdr *m,
                                  const struct iovec *iv, unsigned long total_len,
                                  size_t count, int noblock) {
    struct sk_buff *skb;
    ssize_t ret = 0;
    int zerocopy = 0;

    if (!q || !m || !iv || total_len == 0 || count == 0) {
        return -EINVAL;
    }

    if (m->msg_flags & MSG_ZEROCOPY)
        zerocopy = 1;

    skb = alloc_skb(0, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    if (zerocopy) {
        ret = skb_zerocopy_from_iovec(skb, iv, count, total_len);
    } else {
        ret = skb_copy_from_iovec(skb, iv, count, total_len);
    }

    if (ret < 0)
        goto error;

    skb_set_network_header(skb, 0);

    if (q->vnet_hdr) {
        ret = macvtap_handle_vnet_hdr(skb, q->vnet_hdr);
        if (ret < 0)
            goto error;
    }

    skb->dev = q->vlan_dev;

    if (noblock) {
        ret = dev_queue_xmit(skb);
    } else {
        ret = dev_queue_xmit_nocopy(skb);
    }

    if (ret < 0)
        goto error;

    return total_len;

error:
    kfree_skb(skb);
    return ret;
}

ssize_t macvtap_get_user(struct macvtap_queue *q, struct msghdr *m,
                         const struct iovec *iv, unsigned long total_len,
                         size_t count, int noblock)
{
    struct sk_buff *skb = NULL;
    struct vlan_dev_info *vlan;
    struct net_device *dev;
    size_t len = 0;
    int err = 0;
    int zcopy = 0;
    struct iov_iter iter;
    size_t copied = 0;

    if (!q || !m || !iv || !total_len || !count)
        return -EINVAL;

    dev = q->dev;
    if (!dev)
        return -EINVAL;

    vlan = (struct vlan_dev_info *)dev->priv;
    if (!vlan)
        return -EINVAL;

    if (total_len > dev->mtu + ETH_HLEN)
        return -EMSGSIZE;

    iov_iter_init(&iter, READ, iv, count, total_len);

    skb = alloc_skb(0, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    if (iov_iter_get_pages(&iter, NULL, 0, 0)) {
        zcopy = 1;
    } else {
        zcopy = 0;
    }

    if (zcopy) {
        skb->data = iov_iter_get_pages(&iter, NULL, 0, 0);
        skb->len = total_len;
    } else {
        while (iov_iter_count(&iter)) {
            len = min(iov_iter_count(&iter), (size_t)PAGE_SIZE);
            err = skb_add_data(skb, iov_iter_kmap(&iter, len));
            if (err) {
                kfree_skb(skb);
                return err;
            }
            copied += len;
        }
    }

    skb->protocol = htons(ETH_P_IP);
    skb->dev = dev;

    if (vlan) {
        skb->dev = vlan->real_dev;
        skb->protocol = htons(ETH_P_8021Q);
    }

    err = dev_queue_xmit(skb);
    if (err < 0) {
        kfree_skb(skb);
        return err;
    }

    return (ssize_t)total_len;
}

ssize_t macvtap_get_user_data(struct macvtap_queue *q, struct msghdr *m,
                              const struct iovec *iv, unsigned long total_len,
                              size_t count, int noblock) {
    struct sk_buff *skb = NULL;
    struct virtio_net_hdr virtio_net_hdr;
    int zero_copy = 0;
    ssize_t ret = 0;

    if (!q || !m || !iv || !total_len)
        return -EINVAL;

    if (virtio_net_hdr_from_skb(skb, &virtio_net_hdr))
        return -ENOMEM;

    if (can_zero_copy(q, iv, count)) {
        zero_copy = 1;
        skb = alloc_skb(0, GFP_KERNEL);
        if (!skb)
            return -ENOMEM;
    } else {
        skb = alloc_skb(total_len, GFP_KERNEL);
        if (!skb)
            return -ENOMEM;

        if (copy_from_iter(skb->data, total_len, m->msg_iter) != total_len) {
            kfree_skb(skb);
            return -EFAULT;
        }
    }

    skb_set_network_header(skb, sizeof(struct virtio_net_hdr));

    if (virtio_net_hdr_to_skb(skb, &virtio_net_hdr))
        return -EINVAL;

    if (transmit_skb(skb, q->vlan_dev)) {
        kfree_skb(skb);
        return -EIO;
    }

    ret = total_len;
    return ret;
}
